import json
from pathlib import Path
out=Path(__file__).parent;root=out.resolve().parents[2]
old=json.loads((root/'validation/phesgo-v08412/sources.json').read_text())
sources=[]
for code,pub,versiondate,review,pages,ref in [('00789','2022-12-15','2024-06-07','2029-06-07',10,'turn447view0'),('00790','2022-12-20','2024-07-10','2029-07-10',14,'turn447view1')]:
 prior=next(x for x in old if x['id']==code)
 sources.append({'id':code,'url':prior['url'],'title':'NCCP '+code+' v3','version':'3','published_date':pub,'version_date':versiondate,'review_date':review,'pages':pages,'live_primary_source_browsed':'2026-10-21','web_ref':ref,'prior_local_audit_sha256':prior['sha256'],'prior_hash_retrieved':prior['retrieved'],'fresh_binary_hash_verified':False,'note':'Live official PDF opened and relevant text/tables inspected. Direct binary fetch returned HTTP403; do not present the previous SHA as a fresh hash. Current catalogue itself not separately reconciled by this bounded audit.'})
sources.extend([{'id':'antiemetic','url':'https://healthservice.hse.ie/documents/7180/Supportive_Care_Antiemetics_for_inclusion_NCIS_Medical_Oncology.pdf','version':'8','version_date':'2025-02-10','pages':6,'relevant_pages':[4,5],'live_primary_source_browsed':'2026-10-21','web_ref':'turn466view1'},{'id':'smpc','url':'https://www.ema.europa.eu/en/documents/product-information/phesgo-epar-product-information_en.pdf','pages':61,'relevant_sections':['4.2','4.4'],'live_primary_source_browsed':'2026-10-21','web_ref':'turn474view0'}])
(out/'sources.json').write_text(json.dumps(sources,indent=2)+'\n')
content=[]
for code in ['00789','00790']:
 content.append({'code':code,'file':'data/breast-treatment-journeys-v0837.json','changes':[{'path':f'{code}.lanes[label=Echo / heart tests].cells[1]','proposed':'Every 12 weeks from first HER2 dose; first check around cycle 5 if on time. Earlier for symptoms or concern.','source_ids':[code,'esc','smpc']},{'path':f'{code}.lanes[label=Echo / heart tests].cells[2]','proposed':'Check the last result and next due date before the postoperative plan; do not reset the cardiac clock.','source_ids':[code,'esc','smpc']},{'path':f'{code}.lanes[label=Blood tests].cells[3]','proposed':'Follow the separately selected postoperative regimen and any abnormal results; do not carry over the neoadjuvant Day 8 schedule.','source_ids':[code] if code=='00790' else [code]}],'reason':'Cycle-5 echo currently lives under Surgery/pathology; postoperative blood cell duplicates neoadjuvant requirements.'})
 content.append({'code':code,'file':f'data/patient-knowledge/{code}.json','changes':[{'path':'monitoring_schedule.rows[label=Scans / cancer markers].cells[2]','proposed':'Response imaging at the MDT-selected time; not automatically tied to the week-12 echo.','source_ids':['nccp','early']},{'path':'continuation descriptions / support / phase chapter','proposed':'Use plain language: After surgery, the team chooses the next HER2 medicine from the pathology results. Its own monitoring and supportive plan applies. Do not instruct patients about metastatic regimen code 00785.','source_ids':['nccp']}],'reason':'The fixed week-12 column may imply a universal imaging date that NCCP does not specify. Internal coding guidance is inappropriate patient-facing prose.'})
 content.append({'code':code,'file':'data/phase-support-v0838.json','changes':[{'path':f'regimens.{code}[id=continuation].additional_support','proposed':'The selected postoperative regimen determines emetic risk, premedication and tests. Phesgo or trastuzumab alone generally needs no routine antiemetic prophylaxis; this statement must not be applied automatically to an antibody-drug conjugate. Open the selected regimen before issuing a supportive prescription.','source_ids':['nccp','antiemetic']},{'path':f'regimens.{code}[id=continuation].source_page','proposed':1,'reason':'Postoperative selection is on p1; TRAIN-2 p8 is a count table, not the postoperative or minimal-emetic source.'}],'reason':'Empty orders are appropriate, but the unknown postoperative medicine should not inherit a minimal-risk plan simply because it is HER2-directed.'})
(out/'content-proposals.json').write_text(json.dumps(content,indent=2)+'\n')
